"""Frozen descriptive F1-F4 and explicitly prescribed truth-based transfer."""
from common import *
import pandas as pd
ORDER=['Q_DBL','Q_LCB','Q_DBL_LCB','Q_POW']
def conclusions_text(means,tr,qbias,advbias):
 p=means.loc['Q_POW'];d=means.loc['Q_DBL'];a=means.loc['AL rule'];b=means.loc['Band-train'];o=means.loc['Oracle-8'];fix=means.loc[tr['chosen']]
 text='\nPlain interpretation at5bps: flat-entry Q bias is '+f'{qbias:+.6f}bps and entry-minus-stay advantage bias is {advbias:+.6f}bps.'
 if p.turnover<a.turnover and p.turnover<o.turnover:text+=' POW nevertheless has lower total turnover than both AL and Oracle. Its broader entry-bin policy is not evidence that aggregate trading frequency explains its loss; its much longer holding spells also matter.'
 text+=f' Double changes net by {d.true_value-p.true_value:+.6f}bps/year and turnover by {d.turnover-p.turnover:+.6f}/year. Its gross-value change is {d.gross_value-p.gross_value:+.6f}bps/year. Thus improved net here cannot be described as a reduction in trading costs when turnover rises.'
 text+=f' LCB alone yields {means.loc["Q_LCB","true_value"]:.6f}bps/year. The transfer choice {tr["chosen"]} yields {fix.true_value:.6f}bps/year, versus AL {a.true_value:.6f} and Band {b.true_value:.6f}; its shortfall to Band is {b.true_value-fix.true_value:.6f}bps/year.'
 text+=' These fixed interventions are descriptive evidence about optimism and policy quality, not unique identification of maximisation bias as the cause.\n\n'
 text+='Realised entry probability conditional on an eligible flat observation: '+', '.join(f'{name} {means.loc[name,"entry_rate_given_eligible_flat"]:.2%}' for name in ['Q_POW','Q_LCB','Q_DBL','Q_DBL_LCB'])+'. The table above uses all flat observations, including ineligible ones, as its denominator; both denominators are retained in the CSVs.\n\n'
 text+='Core transfer: use '+tr['chosen']+' as the prescribed Q candidate and retain AL/Band as controls. The sign predictions versus AL and Band are recorded explicitly in q_transfer.json; selecting a Q candidate does not assert that it outperforms those controls or that it will profit on real data.\n'
 return text
def csvout(name,df):publish(RUN/name,df.to_csv(index=False,float_format='%.17g',lineterminator='\n'))
def transfer(frame):
 g=frame[frame.cost==5].groupby('learner',sort=False).mean(numeric_only=True);best=max(g.loc[n,'true_value'] for n in ORDER);eligible=[n for n in ORDER if g.loc[n,'true_value']>=best-1];chosen=eligible[0];rows={}
 for name in ORDER:
  z=frame[(frame.cost==5)&(frame.learner==name)];mean=g.loc[name];rows[name]=dict(mean_true_net=float(mean.true_value),turnover=float(mean.turnover),mean_entry_bins=float(mean.number_entry_bins),entry_bins_by_world=[dict(world=int(r.world),bins=json.loads(r.entry_bins)) for r in z.itertuples()],realised_entry_rate_given_flat=float(mean.entry_rate_given_flat),realised_entry_rate_given_eligible_flat=float(mean.entry_rate_given_eligible_flat),realised_entries_per_series_year=float(mean.entries_per_series_year),gain_vs_AL=float(mean.true_value-g.loc['AL rule','true_value']),gain_vs_Band=float(mean.true_value-g.loc['Band-train','true_value']),sign_vs_AL=int(np.sign(mean.true_value-g.loc['AL rule','true_value'])),sign_vs_Band=int(np.sign(mean.true_value-g.loc['Band-train','true_value'])))
 return dict(chosen=chosen,cost=5,criterion='highest mean true MC net across20worlds; within1bps ofmaximum use DBL,LCB,DBL_LCB,POW',maximum_mean_true_net=float(best),within_1bps=eligible,learners=rows,real_trials=552,new_real_trials=0,scope='IC-matched fixed synthetic best point; increment-R2 mismatch remains; K1-like residual-unit costs; not evidence of real portfolio profitability',SE_label=spec()['LCB']['label'])
def render(result):
 f=pd.DataFrame(result['rows']);b=pd.DataFrame(result['bias']);e=pd.DataFrame(result['entries']);primary=f[f.cost==5];means=primary.groupby('learner').mean(numeric_only=True);powbias=b[(b.cost==5)&(b.learner=='Q_POW')&(b.continuation=='deployed')&(b.state_kind=='flat')&(b.action==1)];qb=float(powbias.bias.mean());ab=float(powbias.advantage_bias.mean());qentry=float(powbias.learned_Q.mean());tentry=float(powbias.true_Q.mean());bin_diff=float(means.loc['Q_POW','number_entry_bins']-means.loc['Oracle-8','number_entry_bins']);bestq=max(means.loc[n,'true_value'] for n in ORDER);band=float(means.loc['Band-train','true_value']);pred=[dict(id='F1',supported=bool(qb>0 and bin_diff>0),entry_Q_bias=qb,entry_advantage_bias=ab,entry_bin_difference_vs_Oracle=bin_diff,criterion='positive mean flat-entry Q bias AND more mean entrybins thanOracle'),dict(id='F2',supported=bool(means.loc['Q_DBL','turnover']<means.loc['Q_POW','turnover'] and means.loc['Q_DBL','true_value']>means.loc['Q_POW','true_value']),net_gain=float(means.loc['Q_DBL','true_value']-means.loc['Q_POW','true_value']),turnover_change=float(means.loc['Q_DBL','turnover']-means.loc['Q_POW','turnover'])),dict(id='F3',supported=bool(means.loc['Q_LCB','true_value']>means.loc['Q_POW','true_value']),net_gain=float(means.loc['Q_LCB','true_value']-means.loc['Q_POW','true_value'])),dict(id='F4',supported=bool(bestq>=band-30),shortfall_vs_Band=band-bestq,criterion='bestQ >= Band-30; superiority also qualifies')]
 tr=transfer(f);csvout('cells.csv',f.drop(columns='policy'));csvout('q_bias.csv',b);csvout('entries.csv',e);csvout('predictions.csv',pd.DataFrame(pred));write(RUN/'q_transfer.json',tr);write(RUN/'policies.json',dict(rows=[{k:r[k] for k in ['world','cost','learner','policy']} for r in result['rows']]))
 names=['Q_POW','Q_DBL','Q_LCB','Q_DBL_LCB','AL rule','Band-train']
 lines=[f'F1: learned flat-entry Q={qentry:.6f}, true Q={tentry:.6f}, bias={qb:.6f}, advantage bias={ab:.6f}; mean extra entrybins vsOracle={bin_diff:.3f}.', 'c=5 net/turnover: '+', '.join(f'{n}={means.loc[n,"true_value"]:.6f}/{means.loc[n,"turnover"]:.6f}' for n in names)+'.', 'F2-F4: '+', '.join(f'{p["id"]}={p["supported"]}' for p in pred[1:])+'.', 'Transfer: '+tr['chosen']+'; fixed within1bps simplicity rule.']
 columns=['true_value','turnover','holding_period','entries_per_series_year','entry_rate_given_flat','number_entry_bins'];table='| learner | '+' | '.join(columns)+' |\n|---|'+'---:|'*len(columns)+'\n'
 for n in names:table+='| '+n+' | '+' | '.join(f'{means.loc[n,k]:.6f}' for k in columns)+' |\n'
 text='# Synthetic Q-learning bias and entry fixes\n\n'+'\n\n'.join(lines)+'\n\n'+table+'\n\n'
 text+='The original AL, Band, Oracle and POW training/test stream hashes and sealed test/truth values were reproduced exactly on all20worlds at5/10bps before any Double production fit. POW and its target-variance diagnostics are authenticated source fits; Q_LCB changes deployment only. Q_DBL_LCB reuses the same Double fits. No new real trials; count552.\n\n'
 text+='LCB: '+spec()['LCB']['label']+'. Per-seed sd(target)*sqrt(V); average A/B, then10seeds without sqrt10 reduction; two actions combined in quadrature, threshold1.645. Nonfinite uncertainty disallows entry. Holding decisions remain greedy. This rule does not estimate independent-training-data uncertainty. Realised entry rates and eligibility denominators are reported in entries.csv/cells.csv, so blocked entry and forced invalid closure remain visible.\n\n'
 text+='Q diagnostics average counterfactual finite-episode returns over the original independent truth histories at every valid decision time, including60session histories and explicit terminal liquidation. Flat states use inventory0; holding states use both signed inventories. A backward path recursion follows the learner policy after one specified action; it never replaces history by a1D Markov state. MC SEs cluster by independent episode-year. All learners share this reference history distribution, rather than learner-dependent occupancy. For LCB, deployed and unrestricted-greedy continuation are both shown when different. LearnedQ is compared with binned finite-horizon policyQ: state aliasing and missing time-to-terminal can also contribute to gaps. Absolute optimism alone does not establish that maximisation caused over-trading; inspect the advantage bias and the fixed intervention comparisons.\n\n'
 text+='All fixes use the unchanged rolling score/validity/half-life mask,8state mapping, reward, epsilon schedule, gamma1,10original seeds, POW exponent and epochcap. Double uses independent seeded fair table coins and per-table counts, selecting next action in the updating table and evaluating in the other. Behaviour/stopping uses the mean A/B table. Costs are per-side residual-unit K1-like fees, not real K2 portfolio costs.\n\n'
 text+='The source fixedOU+RW family matchedIC approximately but undershot increment-R2 excess by84%; that limitation is retained. Transfer is the requested synthetic truth-based choice, not a real-data selection or an externally validated winner. Truth sample reuse is explicit. Results support only this synthetic family.\n\n'
 text+='Method reference: [van Hasselt2010, Double Q-learning](https://papers.nips.cc/paper/3964-double-q-learning.pdf). Exact source trainer body and running target-variance/weight-square formula are imported from the sealed SPI/OU lineage.\n'
 text+=conclusions_text(means,tr,qb,ab)
 publish(RUN/'README.md',text);write(RUN/'summary.json',dict(lines=lines,predictions=pred,transfer=tr['chosen'],F1=dict(learned_entry_Q=qentry,true_entry_Q=tentry,bias=qb,advantage_bias=ab,extra_entry_bins=bin_diff),real_trials=552,new_real_trials=0));plots(f,b);return lines
def plots(f,b):
 import matplotlib.pyplot as plt
 fig,axes=plt.subplots(1,2,figsize=(12,5))
 for ax,c in zip(axes,[5,10]):
  for name,g in f[f.cost==c].groupby('learner'):ax.scatter(g.turnover,g.true_value,label=name,alpha=.65)
  ax.axhline(0,color='grey',lw=.8);ax.set(title=f'{c}bps per side',xlabel='Turnover per series-year',ylabel='True MC net (bps/series-year)')
 axes[0].legend(fontsize=8);fig.tight_layout();fig.savefig(RUN/'outputs/plots/net_turnover.png',dpi=250);plt.close(fig)
 z=b[(b.cost==5)&(b.continuation=='deployed')&(b.state_kind=='flat')&(b.action==1)];fig,ax=plt.subplots(figsize=(7,6))
 for name,g in z.groupby('learner'):ax.scatter(g.true_Q,g.learned_Q,label=name,alpha=.5)
 lo=min(z.true_Q.min(),z.learned_Q.min());hi=max(z.true_Q.max(),z.learned_Q.max());ax.plot([lo,hi],[lo,hi],color='black',lw=.8);ax.set(xlabel='Own-policy MC entry Q (bps)',ylabel='Learned entry Q (bps)');ax.legend();fig.tight_layout();fig.savefig(RUN/'outputs/plots/entry_Q_bias.png',dpi=250);plt.close(fig)
